dtsPropsFor.Button:
/** Visual style. @default "primary" */
  variant?: "primary" | "danger" | "secondary" | "outline" | "ghost" | "link";
  /** Height / padding. @default "md" */
  size?: "sm" | "md" | "lg" | "icon";
  /** Render as the single child element (Radix Slot) instead of a <button>. @default false */
  asChild?: boolean;
  className?: string;
  children?: React.ReactNode;
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.Card:
/** Adds hover lift + border/shadow transition for clickable cards. @default false */
  interactive?: boolean;
  className?: string;
  /** Compose with CardHeader, CardTitle, CardDescription, CardContent, CardFooter (all exported). */
  children?: React.ReactNode;
  onClick?: React.MouseEventHandler<HTMLDivElement>;

dtsPropsFor.Input:
type?: React.HTMLInputTypeAttribute;
  value?: string | number;
  defaultValue?: string | number;
  placeholder?: string;
  disabled?: boolean;
  required?: boolean;
  name?: string;
  id?: string;
  className?: string;
  /** Set true to show the invalid/danger border. */
  "aria-invalid"?: boolean;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;

dtsPropsFor.Textarea:
value?: string;
  defaultValue?: string;
  placeholder?: string;
  rows?: number;
  disabled?: boolean;
  required?: boolean;
  name?: string;
  id?: string;
  className?: string;
  /** Set true to show the invalid/danger border. */
  "aria-invalid"?: boolean;
  onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;

dtsPropsFor.Label:
/** Associates the label with a form control's id. */
  htmlFor?: string;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Skeleton:
/** Size / shape via utility classes, e.g. "h-4 w-32 rounded-full". */
  className?: string;
  style?: React.CSSProperties;

dtsPropsFor.Avatar:
/** Full name; the first two alphanumeric chars are shown as initials. */
  name: string;
  /** @default "md" */
  size?: "sm" | "md" | "lg";
  className?: string;

dtsPropsFor.Tabs:
/** Value of the tab selected on mount (uncontrolled). */
  defaultValue: string;
  /** Compose TabsList + TabsTrigger + TabsContent (all exported) inside. */
  children: React.ReactNode;
  className?: string;
